// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 value) public {
        vm.assume(value > 0);
        vm.assume(value <= address(this).balance || true);
        // c holds no funds in this scenario; owner is this test contract (deploy sender).
        vm.startPrank(address(this));
        bool ok;
        try c.withdraw(value) { ok = true; } catch { ok = false; }
        vm.stopPrank();
        assertTrue(!ok, "withdraw of positive value from unfunded contract must revert");
    }

    receive() external payable {}
}
